sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    const {
        name,
        elementId
    } = event;
    let {
        colmnData,parFilters
    } = api.state;
    if (name == "NOW_GANTT#COLUMN_HIDE_REQUESTED") {
        colmnData.forEach(item => {
            if (item.name === event.payload) {
                item.hidden = true; // Toggles the hidden attribute
            }
        });
    }
    if (name == 'NOW_GANTT#COLUMNS_CONFIG_UPDATED') {
        let {
            payload
        } = event;
        colmnData = payload;
    }
    if (elementId == 'project_task_chronology_1' && name == "DATA_FETCH_SUCCEEDED" && colmnData.length == 0) {
        colmnData = api.data.project_task_chronology_1.output.result.column_conf;
    }
    const temp = {
        filter: parFilters,
        columnData: Object.values(colmnData)
    };
    api.setState('colmnData', Object.values(colmnData));
    api.data.save_user_preference.execute({
        name: "x_main2_mars_spm_0_u_ptask_chronology",
        value: JSON.stringify(temp)
    });
}
